<?php if ( ! defined('BASEPATH')) exit('No direct script access allowed');class mlotinspection extends CI_Controller {    private $limit = 5;    public function __construct() {        parent::__construct();        $this->load->model(CNFCOMPANY."mlotinspectionmodel");        $this->load->helper('cookie');        $this->load->helper('xssclean');        fnIfCheckUserLoggedIn();    }    public function addedit() {        $ArrData												= array('ArrBasicInfo'=>array(),'VarId'=>'','VarNew'=>0);        $VarId		    									    = $this->uri->segment(4);        if($VarId<>'' && base64_decode(urldecode($VarId))) {            $VarUserId                                          = base64_decode(urldecode($VarId));            $ArrResults     									= $this->mlotinspectionmodel->fnGetInfo('','',$VarUserId);            $ArrData['ArrBasicInfo']	    				    = $ArrResults[0];            $ArrData['VarId']					                = $ArrResults[0]['id'];        } else {            $ArrData['VarNew']  							    = 1;        }        $this->load->view(CNFCOMPANY.'addeditlotinspection',$ArrData);    }    public function updateInfo() {        $VarUserInfo = fnGetUserLoggedInfo(1);        $ArrResult                                              = array();        $VarLevel				    						    = xssclean($this->input->post('l'));        $VarCodeletter				    						= xssclean($this->input->post('cl'));        $VarAql				    						        = xssclean($this->input->post('aq'));        $VarStatus											    = xssclean($this->input->post('s'));        $VarSampleSize											= xssclean($this->input->post('ssize'));        $VarId       											= xssclean($this->input->post('id'));        if($VarLevel<>'') {            $ArrUpdateData                                      = array('id'=>$VarId,'samplesize'=>$VarSampleSize,'companyid'=>$VarUserInfo['companyid'],'level'=>$VarLevel,'codeletter'=>$VarCodeletter,'aql'=>$VarAql,'status'=>$VarStatus,'updatedby'=>$VarUserInfo['id'],'dateupdated'=>date('Y-m-d H:i:s'));            if($VarId=='' || $VarId==0) {                $ArrUpdateData['datecreated']                   = date('Y-m-d H:i:s');            }            $ArrStatus                                          = $this->mlotinspectionmodel->saveInfo($ArrUpdateData);            echo json_encode($ArrStatus);unset($ArrStatus);unset($ArrUpdateData);die;        } else {            $ArrResult['errcode']							    = '-1';            $ArrResult['msg']								    = 'Invalid Input!';        }        echo json_encode($ArrResult);    }    public function manage() {        $VarFrom												= xssclean($this->input->post('rfrom'));        $VarLevel											    = xssclean($this->input->post('l'));        $VarSampleSize  										= xssclean($this->input->post('ss'));        $VarStatus  											= xssclean($this->input->post('s'));        $clickedColumnId  										= xssclean($this->input->post('columnId'));        $newsortorder  										    = xssclean($this->input->post('sortorder'));        $VarAfilter  										    = xssclean($this->input->post('afilter'));        $ArrDbCols = array('i.level','i.codeletter','i.aql','i.samplesize','i.status','u.contactname','i.dateupdated');        if($VarFrom==1) {            $VarURLSegment										= 4;            $this->load->library('pagination');            $config['base_url']									= base_url().CNFCOMPANY.'mlotinspection/manage/';            $config['total_rows']								= $this->mlotinspectionmodel->fnCount($VarLevel,$VarStatus,$VarAfilter);            $config['per_page']									= $this->limit;            $config['uri_segment']								= $VarURLSegment;            $offset												= $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby												= "dateupdated";            $sortorder											= "desc";            if($clickedColumnId <> '' && $newsortorder <> '') {                if(array_key_exists($clickedColumnId,$ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrFabricTypeList								    = $this->mlotinspectionmodel->fnList($VarLevel,$VarStatus,$this->limit,$offset,$sortby,$sortorder,$VarAfilter)->result();            $data['pagination']									= $this->pagination->create_linkswithajax('Inspection');            $i=0;            $ArrFnlList										    = array();            $ArrStatus                                          = unserialize(ARRSTATUS);            foreach ($ArrFabricTypeList as $ObjFabric){                $ArrFnlList[$i]['id']						    = $ObjFabric->id;                $ArrFnlList[$i]['l']						    = $ObjFabric->level;                $ArrFnlList[$i]['cl']						    = $ObjFabric->codeletter;                $ArrFnlList[$i]['aq']						    = $ObjFabric->aql;                $ArrFnlList[$i]['ss']						    = $ObjFabric->samplesize;                $ArrFnlList[$i]['ub']						    = $ObjFabric->contactname;                $ArrFnlList[$i]['s']						    = $ArrStatus[$ObjFabric->status];                $ArrFnlList[$i]['du']						    = date('d-m-Y H:i:s',strtotime($ObjFabric->dateupdated));                $i=$i+1;            }            echo json_encode(array('errcode'=>1,'cn'=>$config['total_rows'],'ct'=>$i,'re'=>$ArrFnlList,'pa'=>base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY.'managelotinspection');        }    }    function changemStatus() {        $VarActDeactOption										= xssclean($this->input->post('actdeactFabType'));        $VarCid 	   										    = xssclean($this->input->post('cid'));        if($VarActDeactOption <> '' && $VarCid <> '') {            $this->mlotinspectionmodel->fnChangeComStat($VarCid,$VarActDeactOption);        }        echo json_encode(array('errcode'=> 1));        die;    }    function delInfo() {        $VarYarnId                                            = xssclean($this->input->post('id'));        $VarUpdatedBy                                           = fnGetUserLoggedInfo();        if($VarYarnId>=1) {            $ArrResult             					            = $this->mlotinspectionmodel->fnDel($VarYarnId,$VarUpdatedBy);        } else {            $ArrResult['errcode']						        = -1;            $ArrResult['msg']							        = '';        }        echo json_encode($ArrResult);    }}